lemma poly_abs_le (a : ℕ → ℝ) (h13 : a 13 = 0) {A : ℝ}
    (hA : ∑ i ∈ Finset.range 14, |a i| ≤ A) {X : ℝ} (hX : 1 ≤ X) :
    |poly a X| ≤ A * X ^ 12

theorem eq_affine_of_linear_growth {g : ℂ → ℂ} (hg : Differentiable ℂ g) {a b : ℝ}
    (ha : 0 ≤ a) (hb : 0 ≤ b) (hgrow : ∀ z, ‖g z‖ ≤ a + b * ‖z‖) :
    ∃ c : ℂ, ∀ z, g z = c * z + g 0

theorem norm_deriv_le_of_linear_growth {g : ℂ → ℂ} (hg : Differentiable ℂ g) {a b : ℝ}
    (ha : 0 ≤ a) (hb : 0 ≤ b) (hgrow : ∀ z, ‖g z‖ ≤ a + b * ‖z‖) (w : ℂ) :
    ‖deriv g w‖ ≤ b

theorem norm_le_linear_of_re_le_linear {g : ℂ → ℂ} (hg : Differentiable ℂ g) {L B : ℝ}
    (hB : 0 ≤ B) (hre : ∀ z, (g z).re ≤ L + B * ‖z‖) (z : ℂ) :
    ‖g z‖ ≤ (2 * |L| + 4 * B + 2 + 3 * ‖g 0‖) + 4 * B * ‖z‖

theorem deriv_deriv_eq_zero_of_sqrt_growth {g : ℂ → ℂ} (hg : Differentiable ℂ g) {K : ℝ}
    (hK : 0 ≤ K) (hgrow : ∀ w, ‖deriv g w‖ ≤ K * Real.sqrt (1 + ‖w‖)) (w : ℂ) :
    deriv (deriv g) w = 0

theorem exists_poly_mul_exp_of_finite_zeros_of_hasOrderLeOne {f : ℂ → ℂ}
    (hf : Differentiable ℂ f) (hord : HasOrderLeOne f) (hfin : {z : ℂ | f z = 0}.Finite) :
    ∃ (P : Polynomial ℂ) (a b : ℂ), ∀ z, f z = P.eval z * Complex.exp (a * z + b)

theorem norm_deriv_le_sqrt_of_phi32_growth {g : ℂ → ℂ} (hg : Differentiable ℂ g) {K : ℝ}
    (hK : 0 ≤ K) (hgrow : ∀ z, ‖g z‖ ≤ K * phi32 ‖z‖) (w : ℂ) :
    ‖deriv g w‖ ≤ 6 * K * Real.sqrt (1 + ‖w‖)

theorem norm_le_phi32_of_re_le_phi32 {g : ℂ → ℂ} (hg : Differentiable ℂ g) {L B : ℝ}
    (hB : 0 ≤ B) (hre : ∀ z, (g z).re ≤ L + B * phi32 ‖z‖) (z : ℂ) :
    ‖g z‖ ≤ (2 * |L| + 12 * B + 2 + 3 * ‖g 0‖) * phi32 ‖z‖
